-- undo: update public.published_recipes set diets = array_append(diets, 'no-gluten'), recipe = jsonb_set(recipe, '{diets}', (recipe->'diets') || '["no-gluten"]'::jsonb) where id = 'a56305b5-f5f2-4b63-a87c-c1890308be4e';

